import { apiClient, unwrap, type BffResponse } from '../api';
import { fpcEndpoint } from './endpoint';
import type {
  CostPlanItemDto,
  PlanVoucherFilterDto,
  PlanVoucherImportRequestDto,
  PlanVoucherImportResultDto,
  PlanVoucherListPageDto,
} from './types';

const PLAN_VOUCHER_BASE = '/fpc/plan-vouchers';

/**
 * FPC API facade.
 * Plan-voucher import/lines are implemented here (own properties) so webpack
 * TS check always has them — independent of named re-exports on endpoint.
 */
export const fpcService = {
  ...fpcEndpoint,

  getPlanVoucherList: (
    params?: PlanVoucherFilterDto,
  ): Promise<PlanVoucherListPageDto> => fpcEndpoint.getPlanVoucherList(params),

  /** CostPlan lines scoped to voucher (cross-company safe on BE). */
  getPlanVoucherLines: async (id: string): Promise<CostPlanItemDto[]> => {
    const res = await apiClient.get<BffResponse<CostPlanItemDto[]>>(
      `${PLAN_VOUCHER_BASE}/${id}/lines`,
    );
    return unwrap(res) ?? [];
  },

  /** Download template Excel (dropdown MaDonVi / MaChiPhi + tab tham chiếu). */
  downloadPlanVoucherImportTemplate: async (): Promise<void> => {
    const blob = await apiClient.getBlob(`${PLAN_VOUCHER_BASE}/import/template`);
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'mau-import-phieu-ke-hoach.xlsx';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
  },

  /** Import rows parsed from Excel → create/reuse PKH + upsert CostPlan. */
  importPlanVouchers: async (
    dto: PlanVoucherImportRequestDto,
  ): Promise<PlanVoucherImportResultDto> => {
    const res = await apiClient.post<BffResponse<PlanVoucherImportResultDto>>(
      `${PLAN_VOUCHER_BASE}/import`,
      dto,
    );
    return unwrap(res);
  },
};
