// ── Helpers ─────────────────────────────────────────────────────

function buildQs(params: object) {
  const qs = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v !== undefined && v !== null && v !== '') qs.set(k, String(v));
  });
  return qs.toString();
}

function asList<T>(data: unknown): T[] {
  if (Array.isArray(data)) return data as T[];
  const d = data as { items?: T[] };
  if (Array.isArray(d?.items)) return d.items;
  return [];
}

function asPagedList<T>(
  data: unknown,
  fallbackPage = 1,
  fallbackPageSize = 20,
): { items: T[]; totalCount: number; page: number; pageSize: number } {
  if (Array.isArray(data)) {
    return {
      items: data as T[],
      totalCount: data.length,
      page: fallbackPage,
      pageSize: fallbackPageSize,
    };
  }
  const d = data as {
    items?: T[];
    totalCount?: number;
    page?: number;
    pageSize?: number;
  };
  const items = Array.isArray(d?.items) ? d.items : [];
  return {
    items,
    totalCount: typeof d?.totalCount === 'number' ? d.totalCount : items.length,
    page: typeof d?.page === 'number' ? d.page : fallbackPage,
    pageSize: typeof d?.pageSize === 'number' ? d.pageSize : fallbackPageSize,
  };
}

