async function getPlanVoucherListPaged(
  params?: PlanVoucherFilterDto,
): Promise<PlanVoucherListPageDto> {
  const page = params?.page ?? 1;
  const pageSize = params?.pageSize ?? 20;
  const qs = params ? `?${buildQs(params)}` : '';
  const res = await apiClient.get<
    BffResponse<PlanVoucherListPageDto | PlanVoucherDraftDto[]>
  >(`${BASE}/plan-vouchers${qs}`);
  const paged = asPagedList<PlanVoucherDraftDto>(unwrap(res), page, pageSize);
  return {
    items: paged.items,
    totalCount: paged.totalCount,
    page: paged.page,
    pageSize: paged.pageSize,
  };
}

